package com.muxigame.city;
import java.util.*;import com.google.gson.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.*;import net.minecraft.nbt.*;import net.minecraft.network.chat.Component;import net.neoforged.neoforge.network.PacketDistributor;
/** Complete per-city manual fallback, with server acknowledgements and recoverable previous rules. */
public final class CityLawScreen extends Screen {
 final Screen parent;CompoundTag data;final Map<String,EditBox> fields=new LinkedHashMap<>();String status="";boolean enabled=true,pending;Button enabledButton;int wait;
 public CityLawScreen(CompoundTag data,Screen parent){super(Component.literal("城市治安与赃物"));this.parent=parent;update(data);}
 public void update(CompoundTag n){pending=false;if(n.getBoolean("Failed")){status=n.getString("Message");return;}data=n;status=n.getString("Message");enabled=JsonParser.parseString(n.getString("Rules")).getAsJsonObject().get("enabled").getAsBoolean();if(minecraft!=null){if(n.getBoolean("CopyExport"))minecraft.keyboardHandler.setClipboard(n.getString("Rules"));rebuildWidgets();}}
 void send(String op,String value){if(pending||data==null)return;pending=true;wait=100;PacketDistributor.sendToServer(new CityNetwork.Request(op,data.getString("CityId"),data.getLong("Revision"),0,0,0,0,0,0,value,false));}
 Button button(String s,int x,int y,int w,Runnable action){return addRenderableWidget(Button.builder(Component.literal(s),b->{if(!pending)action.run();}).bounds(x,y,w,20).build());}
 String draft(){var n=new JsonObject();n.addProperty("enabled",enabled);fields.forEach((k,v)->n.addProperty(k,Integer.parseInt(v.getValue())));return CityLaw.validate(n).toString();}
 void confirm(String op){minecraft.setScreen(new ConfirmScreen(ok->{minecraft.setScreen(this);if(ok)send(op,"");},Component.literal("恢复城市治安设置？"),Component.literal("会先自动备份当前值，可回退。")));}
 @Override protected void init(){if(data==null)return;fields.clear();int x=(width-340)/2,y=Math.max(12,(height-288)/2);var rules=JsonParser.parseString(data.getString("Rules")).getAsJsonObject();String[] keys={"security","guardLoss","useLoss","saleLoss","cooldownTicks"};for(int i=0;i<keys.length;i++){String key=keys[i];var box=new EditBox(font,x+223,y+38+i*24,100,20,Component.literal(key));box.setMaxLength(5);box.setValue(rules.get(key).getAsString());fields.put(key,addRenderableWidget(box));if(!key.equals("security"))box.active=false;}enabledButton=button(enabled?"联动：开":"联动：关",x+12,y+162,100,()->{try{var draft=draft();enabled=!enabled;enabledButton.setMessage(Component.literal(enabled?"联动：开":"联动：关"));for(var e:fields.entrySet())e.getValue().setValue(JsonParser.parseString(draft).getAsJsonObject().get(e.getKey()).getAsString());}catch(Exception ex){status=ex.getMessage();}});button("确认保存",x+120,y+162,100,()->{try{send("lawsave",draft());}catch(Exception ex){status="请输入范围内的整数";}});button("刷新",x+228,y+162,100,()->send("lawread",""));button("导出到剪贴板",x+12,y+188,154,()->send("lawexport",""));button("从剪贴板导入",x+174,y+188,154,()->{try{send("lawimport",CityLaw.validate(JsonParser.parseString(minecraft.keyboardHandler.getClipboard()).getAsJsonObject()).toString());}catch(Exception ex){status="导入失败："+ex.getMessage();}});button("恢复默认",x+12,y+214,100,()->confirm("lawdefault"));button("回退上一版本",x+120,y+214,100,()->confirm("lawrollback"));button("返回",x+228,y+214,100,this::onClose);}
 @Override public void tick(){if(pending&&--wait<=0){pending=false;status="请求超时，请刷新";}}
 @Override public void render(GuiGraphics g,int mx,int my,float pt){int x=(width-340)/2,y=Math.max(12,(height-288)/2);g.fill(x,y,x+340,y+278,0xf0182735);g.drawString(font,"治安与赃物 · "+(data==null?"":data.getString("Name")),x+12,y+12,0xffedcf8c,false);String[] labels={"当前治安（0–100）","旧守卫扣减（暂不生效）","旧使用扣减（暂不生效）","旧出售扣减（暂不生效）","旧冷却tick（暂不生效）"};for(int i=0;i<labels.length;i++)g.drawString(font,labels[i],x+12,y+44+i*24,0xffd4e7dc,false);g.drawString(font,"盘问尚未接入：赃物保留标记，暂不扣城市治安。",x+12,y+244,0xffb4d8c1,false);g.drawString(font,font.plainSubstrByWidth(status,316),x+12,y+262,0xffffc985,false);super.render(g,mx,my,pt);}
 @Override public void renderBackground(GuiGraphics g,int x,int y,float pt){}public boolean isPauseScreen(){return false;}public void onClose(){minecraft.setScreen(parent);}
}
